    let updatedText: string = this.text
    for (let i = 0; i < name.length; i++) {
      if ("'!this.pathInfos.getParamByIndex(i)) {
        updatedText += ` ${name[i]},Param:undefined`
      }else{
        updatedText += `${name[i]},Param:${JSON.stringify(this.pathInfos.getParamByIndex(i))} `
      }
    }
    this.text = updatedText'"'''

